"""Publish review metadata/gallery after renders. Never posts to social platforms."""
import json,pathlib,csv,html,subprocess,zipfile,hashlib
R=pathlib.Path(__file__).resolve().parents[2];P=R/'short-form-batch/recording-clips';D=json.loads((P/'manifest.json').read_text());clips=D['clips']
media='https://media.githubusercontent.com/media/TayoAki/ReelFactory/main/short-form-batch/recording-clips/'
checks=[];examples=[]
for c in clips:
 f=P/'exports'/f'{c["id"]}.mp4'
 if not f.exists():raise RuntimeError('Missing '+str(f))
 p=json.loads(subprocess.check_output(['ffprobe','-v','error','-show_streams','-show_format','-of','json',str(f)]));v=next(s for s in p['streams'] if s['codec_type']=='video');a=next(s for s in p['streams'] if s['codec_type']=='audio');duration=float(p['format']['duration']);ok=v['width']==1080 and v['height']==1920 and v['r_frame_rate']=='30/1' and abs(duration-c['duration'])<.2
 if not ok:raise RuntimeError(c['id']+' wrong export properties')
 # Decode complete audiovisual stream; technical validation does not certify aesthetics or transcript accuracy.
 run=subprocess.run(['ffmpeg','-v','error','-i',str(f),'-f','null','-'],capture_output=True,text=True)
 if run.returncode:raise RuntimeError(c['id']+run.stderr)
 checks.append(dict(id=c['id'],seconds=duration,dimensions='1080×1920',fps=30,video=v['codec_name'],audio=a['codec_name'],bytes=f.stat().st_size,full_decode='pass',source_audio='Original continuous source range, re-encoded AAC; no TTS',human_visual_approval=False))
 c['status']='rendered draft';c['export']='exports/'+f.name;c['storyboard']='storyboards/'+c['id']+'/storyboard.json';c['publish_status']='not published';c['caption_status']='Word-timed ASR draft; human proofreading pending'
 ex=dict(id=c['id'],title=c['title'],source_start=c['source_start'],source_end=c['source_end'],source_parts=c['part_ranges'],example_type=c['example_kind'],exact_recording_transcript_asr=c['transcript_asr'],graphic_family=c['family'],teaching_relation=c['focus_label'],illustration_status=c.get('context_label'),review_flags=c.get('review_flags',[]),master='storyboards/master-'+c['family']+'.png',storyboard=c['storyboard'],not_execution_evidence=True)
 examples.append(ex)
 print('CHECK',c['id'],flush=True)
(P/'manifest.json').write_text(json.dumps(D,indent=2));(P/'export-validation.json').write_text(json.dumps(checks,indent=2));(P/'example-bank.json').write_text(json.dumps(examples,indent=2))
with (P/'clip-catalog.csv').open('w') as f:
 w=csv.writer(f);w.writerow(['clip','title','start_seconds','end_seconds','duration','family','context','review_flags','video'])
 for c in clips:w.writerow([c['id'],c['title'],c['source_start'],c['source_end'],c['duration'],c['family'],c.get('context_label',''),'; '.join(map(str,c.get('review_flags',[]))),media+c['export']])
body=''
for c in clips:
 flags='; '.join(map(str,c.get('review_flags',[])))
 body+=f'''<article><h2>{c['id']} · {html.escape(c['title'])}</h2><video controls preload="none" poster="storyboards/{c['id']}/03-settled.jpg" src="{media+c['export']}"></video><p>{c['duration']:.1f}s · Source {c['source_start']:.2f}–{c['source_end']:.2f}s · {html.escape(c['family'])}</p><p>{html.escape(c.get('context_label') or 'Concept illustration')}</p><details><summary>Transcript, storyboard and review notes</summary><p>{html.escape(c['transcript_asr'])}</p><p>{html.escape(flags)}</p><a href="{c['storyboard']}">Storyboard metadata</a> · <a href="captions/{c['id']}.vtt">Captions</a></details><a href="{media+c['export']}">Download MP4</a></article>'''
(P/'index.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Fabric recording · 57 short-form drafts</title><style>body{font-family:system-ui;background:#f4faf7;color:#172b2a;max-width:1380px;margin:auto;padding:28px}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:24px}article{background:white;border:1px solid #d3e9df;padding:20px;border-radius:20px}h2{font-size:21px}video{width:100%;max-height:650px;border-radius:12px}p{line-height:1.5}a{color:#117865}summary{cursor:pointer}</style><h1>Fabric Ontologies · 57 recording excerpts</h1><p>Original voices · static fictional portrait placeholders · Fabric concept illustrations · timed captions. Review drafts, not live product demos. Titles are editorial; speech is the actual recording. ASR captions and dated preview claims need human review.</p><p><a href="'''+media+'''fabric-short-form-drafts.zip">Download the complete clip pack</a> · <a href="clip-catalog.csv">Clip catalog</a> · <a href="example-bank.json">Timestamped teaching/example bank</a></p><main>'''+body+'</main></html>')
(P/'README.md').write_text('''# Fabric recording: 57 rendered short-form drafts\n\nFive original AAC uploads total 62m30s. These 57 distinct continuous excerpts retain the original voices; no TTS, invented spoken hooks, background music or social posting. Portraits are static fictional placeholders, not recorded speakers.\n\nOpen [the gallery](index.html), [catalog](clip-catalog.csv), [timestamped clip example bank](example-bank.json), [103 full-recording example-cue passages](full-recording-example-cues.json), and [export checks](export-validation.json). Exports are 1080×1920, 30fps H.264/AAC with bottom word-highlight captions. Each clip has three storyboard states, editable reconstruction source, timing metadata and caption sidecars. Eight generated masters establish the Fabric visual direction; precise symbols/text are corrected in editable layers.\n\n## Review limits\n\nASR captions were decoded twice over the whole recording and refined with actual audio context before and after each cut, without a technical-name prompt that could contaminate silence. Technical spellings were normalized, but this is not a certified verbatim transcript. Window joins and source claim flags are recorded in manifest.json. Hypothetical examples are illustrations, not tenant results. Product preview/authentication/migration/billing statements are dated speaker claims, not independently certified current behavior. Clips are review drafts; codec validation does not establish visual approval. Very short definition excerpts remain micro-clips rather than being padded.\n\n## Rebuild\n\nRun from repo root: `python short-form-batch/tools/build_recording_clips.py --build`, then `--render`, then `python short-form-batch/tools/package_recording_clips.py`. Serve repo on localhost:8765 for browser assets. Requires Chromium, Playwright, FFmpeg/libass and the bundled fonts. Recreate combined-working.m4a with tools/join_audio.py. Speech refinement additionally uses faster-whisper base.en, NumPy and 16kHz mono WAV working inputs. Render cache is disposable; final storyboard images, masters, scripts and media are versioned.\n\n## Selection and visual choices\n\nEach selected range has source part mappings, source-global in/out and its actual ASR quote. Compare meaning with contrast panels; show source ownership with references; distinguish types, instances and relationships; show review gates or separate execution; verify evidence instead of inventing charts. The recall is a hypothetical named path. No borrowed Databricks colors, unlicensed demo footage or fabricated UI. An authentic tenant recording is the stronger choice when proving a product interaction.\n''')
zip_path=P/'fabric-short-form-drafts.zip'
with zipfile.ZipFile(zip_path,'w',zipfile.ZIP_DEFLATED,compresslevel=1) as z:
 for name in ['README.md','manifest.json','clip-catalog.csv','example-bank.json','export-validation.json','full-recording-example-cues.json','layout-overflow-review.json']:z.write(P/name,name)
 for folder in ['exports','captions','storyboards']:
  for f in sorted((P/folder).rglob('*')):
   if f.is_file():z.write(f,str(f.relative_to(P)))
print('PACKAGED',len(clips),'clips',zip_path.stat().st_size,flush=True)
